/* routine.c */
void SetRegisterField(unsigned int reg, unsigned int offset, unsigned int width, unsigned int value)
{
	unsigned int result;
	unsigned int original;
	unsigned int mask;
	unsigned int value_masked;

	original = *(volatile unsigned int *)reg;

	if (width == 32)
		mask = 0xffffffff;
	else
		mask = (1 << width) - 1;
	value_masked = value & mask;
	result = (original & (~(mask << offset))) | (value_masked << offset);

	*(volatile unsigned int *)reg = result;
}

unsigned int GetRegisterField(unsigned int reg, unsigned int offset, unsigned int width)
{
	unsigned int result;
	unsigned int original;
	unsigned int mask;
	unsigned int mask_shifted;

	original = *(volatile unsigned int *)reg;
	if(width==32)
		mask = 0xffffffff;
	else
		mask = (1 << width)-1;
	mask_shifted = mask << offset;
	result = (original & mask_shifted) >> offset;

	return result;
}

/* databahn.c */
void Databahn_Init(void)
{
	volatile unsigned int i;

#if 0
#ifdef CONFIG_DDR3
	//DDR3
	*(volatile unsigned int*)(CONFIG_BASE + CONFIG_SOURCE_SEL)            |= (1<<25);
	*(volatile unsigned int*)(CONFIG_BASE + CONFIG_MPEG_CLK_INHIBIT_NORM) &= ~((1<<27)|(1<<28));
	*(volatile unsigned int*)(CONFIG_BASE + CONFIG_DENALI_CONFIG0)         = 0xffffffff;
	*(volatile unsigned int*)(CONFIG_BASE + CONFIG_DRAM_CONFIG1)           = (1<<22)|1|(4<<4)|(4<<8)|(4<<12)|(4<<16);
	*(volatile unsigned int*)(CONFIG_BASE + CONFIG_DRAM_CONFIG0)           = 2|(1<<3)|(1<<12)|(1<<13)|(1<<14)|(14<<4)|(14<<8)|(14<<16)|(14<<20)|(3<<24)|(3<<28);
	//*(volatile unsigned int*)(CONFIG_BASE + CONFIG_DRAM_CONFIG0)           = 2|(1<<3)|(1<<12)|(1<<13)|(1<<14)|(7<<4)|(7<<8)|(7<<16)|(7<<20)|(3<<24)|(3<<28);	//new parameters, for tmp try
#elif defined(CONFIG_DDR2)
	//DDR2
	*(volatile unsigned int*)(CONFIG_BASE+CONFIG_SOURCE_SEL) |= (1<<25);
	*(volatile unsigned int*)(CONFIG_BASE+CONFIG_MPEG_CLK_INHIBIT_NORM) &= ~((1<<27)|(1<<28));
	*(volatile unsigned int*)(CONFIG_BASE+CONFIG_DENALI_CONFIG0)=0xffffffff;
	*(volatile unsigned int*)(CONFIG_BASE+CONFIG_DRAM_CONFIG0)=7|(1<<3)|(1<<12)|(14<<4)|(14<<8)|(14<<16)|(14<<20)|(1<<24)|(1<<28);//OK
	//*(volatile unsigned int*)(CONFIG_BASE+CONFIG_DRAM_CONFIG0)=7|(1<<3)|(1<<12)|(7<<4)|(7<<8)|(7<<16)|(7<<20)|(1<<24)|(1<<28);	//new parameters, for tmp try
	*(volatile unsigned int*)(CONFIG_BASE+CONFIG_DRAM_CONFIG1)=3|(6<<4)|(6<<8)|(6<<12)|(6<<16)|(0<<22)|(1<<20);
#else
#error "you must define CONFIG_DDR3 or CONFIG_DDR2"
#endif


	// vref
	*(volatile unsigned int*)(CONFIG_BASE+CONFIG_DRAM_CONFIG1)|=(1<<11)|(1<<19);
	// data_e
	*(volatile unsigned int*)(CONFIG_BASE+CONFIG_DRAM_CONFIG0)|=(1<<15);
	// 1t
	*(volatile unsigned int*)(CONFIG_BASE+CONFIG_DRAM_CONFIG1)|=(1<<2);
#endif

	*(volatile unsigned int*)(CONFIG_BASE+CONFIG_SOURCE_SEL) |= (1<<25);
	*(volatile unsigned int*)(CONFIG_BASE+CONFIG_MPEG_CLK_INHIBIT_NORM) &= ~((1<<27)|(1<<28));
	*(volatile unsigned int*)(CONFIG_BASE+CONFIG_DENALI_CONFIG0)=0xffffffff;

	*(volatile unsigned int*)(CONFIG_BASE+CONFIG_MPEG_CLD_RST_NORM) |= (0x1);
	*(volatile unsigned int*)(CONFIG_BASE+CONFIG_MPEG_CLD_RST_NORM) &= ~(0x1);


	*(volatile unsigned int*)(CONFIG_BASE+CONFIG_DRAM_CONFIG0)&=~(0xffffffff);
	*(volatile unsigned int*)(CONFIG_BASE+CONFIG_DRAM_CONFIG1)&=~(0xffffffff);
	*(volatile unsigned int*)(CONFIG_BASE+CONFIG_DRAM_CONFIG2)&=~(0xffffffff);

#ifdef CONFIG_DDR3
	*(volatile unsigned int*)(CONFIG_BASE+CONFIG_DRAM_CONFIG1)&=~(0x3<<29); // set ddr3
	*(volatile unsigned int*)(CONFIG_BASE+CONFIG_DRAM_CONFIG1)|=(0x2<<29); // set ddr3
	//#elif DDR_VERSION == ddr2
#elif defined(CONFIG_DDR2)
	*(volatile unsigned int*)(CONFIG_BASE+CONFIG_DRAM_CONFIG1)&=~(0x3<<29); // set ddr2
	//    //(volatile unsigned int*)(CONFIG_BASE+CONFIG_DRAM_CONFIG1)|=(0x0<<29); // set ddr2
	//#elif DDR_VERSION == ddr_rdl
	//  *(volatile unsigned int*)(CONFIG_BASE+CONFIG_DRAM_CONFIG1)&=~(0x3<<29); // set ddrRDL
	//  *(volatile unsigned int*)(CONFIG_BASE+CONFIG_DRAM_CONFIG1)|=(0x1<<29); // set ddrRDL
#endif
//ODC PU
	*(volatile unsigned int*)(CONFIG_BASE+CONFIG_DRAM_CONFIG0)&=~(0x7<<0); // set the feed pad ODT
	*(volatile unsigned int*)(CONFIG_BASE+CONFIG_DRAM_CONFIG0)&=~(0x7<<3); // set the feed pad OCD
	*(volatile unsigned int*)(CONFIG_BASE+CONFIG_DRAM_CONFIG0)&=~(0x7<<6); // set the feed pad OCD
	*(volatile unsigned int*)(CONFIG_BASE+CONFIG_DRAM_CONFIG0)&=~(0xf<<16); // dq ocd PU
	*(volatile unsigned int*)(CONFIG_BASE+CONFIG_DRAM_CONFIG0)&=~(0xf<<20); // dq ocd PD
	*(volatile unsigned int*)(CONFIG_BASE+CONFIG_DRAM_CONFIG0)&=~(0x7<<24); // set the dm pad OCD
	*(volatile unsigned int*)(CONFIG_BASE+CONFIG_DRAM_CONFIG1)&=~(0x7<<0); // set the DS pad OCD
	*(volatile unsigned int*)(CONFIG_BASE+CONFIG_DRAM_CONFIG1)&=~(0xf<<3); // dqs ocd PU
	*(volatile unsigned int*)(CONFIG_BASE+CONFIG_DRAM_CONFIG1)&=~(0xf<<7); // dqs ocd PD
	*(volatile unsigned int*)(CONFIG_BASE+CONFIG_DRAM_CONFIG1)&=~(0x7<<11); // set the DS pad OCD
	*(volatile unsigned int*)(CONFIG_BASE+CONFIG_DRAM_CONFIG1)&=~(0xf<<14); // dqs ocd PU
	*(volatile unsigned int*)(CONFIG_BASE+CONFIG_DRAM_CONFIG1)&=~(0xf<<18); // dqs ocd PD
	*(volatile unsigned int*)(CONFIG_BASE+CONFIG_DRAM_CONFIG2)&=~(0x7<<0); // set the DS pad OCD
	*(volatile unsigned int*)(CONFIG_BASE+CONFIG_DRAM_CONFIG2)&=~(0xf<<3); // dqs ocd PU
	*(volatile unsigned int*)(CONFIG_BASE+CONFIG_DRAM_CONFIG2)&=~(0xf<<7); // dqs ocd PD
	*(volatile unsigned int*)(CONFIG_BASE+CONFIG_DRAM_CONFIG2)&=~(0x7<<11); // dqs ocd PD

	*(volatile unsigned int*)(CONFIG_BASE+CONFIG_DRAM_CONFIG0)|= (0x1<<0); //fo 110/2 ŷķ

	*(volatile unsigned int*)(CONFIG_BASE+CONFIG_DRAM_CONFIG0)&=~(0xf<<11); // POWER DOWN

	//PAD low power
	*(volatile unsigned int*)(CONFIG_BASE+CONFIG_DRAM_CONFIG0)&=~(1<<15); //for pad_oe_e.low power
	//*(volatile unsigned int*)(CONFIG_BASE+CONFIG_DRAM_CONFIG0)|=(1<<15); //for pad_oe_e.low power

	*(volatile unsigned int*)(CONFIG_BASE+CONFIG_DRAM_CONFIG0)|=(0x8<<16); //
	//ODC PU
	*(volatile unsigned int*)(CONFIG_BASE+CONFIG_DRAM_CONFIG0)|= (0x8<<20); //

	//dqs PU
	*(volatile unsigned int*)(CONFIG_BASE+CONFIG_DRAM_CONFIG1)|=(0x8<<3); //
	//dqs PU
	*(volatile unsigned int*)(CONFIG_BASE+CONFIG_DRAM_CONFIG1)|= (0x8<<7); //
	//clk PU
	*(volatile unsigned int*)(CONFIG_BASE+CONFIG_DRAM_CONFIG1)|=(0x8<<14); //
	//clk PU
	*(volatile unsigned int*)(CONFIG_BASE+CONFIG_DRAM_CONFIG1)|=(0x8<<18); //
	//address PU
	*(volatile unsigned int*)(CONFIG_BASE+CONFIG_DRAM_CONFIG2)|=(0x8<<3); //
	//address PU
	*(volatile unsigned int*)(CONFIG_BASE+CONFIG_DRAM_CONFIG2)|=(0x8<<7); //

	ddr_config_patch();

	*(volatile unsigned int*)(CONFIG_BASE+CONFIG_DRAM_CONFIG0)|= (0x1<<31);

#if 0   //DDR_VREF_EXTER
	//command ds
	*(volatile unsigned int*)(CONFIG_BASE+CONFIG_DRAM_CONFIG2)&=~(0xf<<16); //
	*(volatile unsigned int*)(CONFIG_BASE+CONFIG_DRAM_CONFIG2)|= (0xf<<16); //
#endif

#if 1   //DDR_VREF_INTE
	*(volatile unsigned int*)(CONFIG_BASE+CONFIG_DRAM_CONFIG2)&=~(0xf<<16); //
	*(volatile unsigned int*)(CONFIG_BASE+CONFIG_DRAM_CONFIG2)|= (0x0<<16); //
#endif


	for(i = 0;i < sizeof(DENALI_CONFIG_CTL)/sizeof(unsigned int); i++)
		*(volatile unsigned int *)Databahn_Reg(i) = DENALI_CONFIG_CTL[i];

	for(i = 0; i < sizeof(DENALI_CONFIG_PHY)/sizeof(unsigned int); i++)
		*(volatile unsigned int *)Databahn_Reg((i + 256)) = DENALI_CONFIG_PHY[i];

	Databahn_Config();

	while(!Databahn_isReady());
}

void Databahn_SetParameters(struct reg_param *regs, int count) {
	int i;

	for (i=0; i < count; i++)
		SetRegisterField(Databahn_Reg(regs[i].reg), regs[i].offset, regs[i].width, regs[i].value);
}

void Databahn_Config(void)
{
	Databahn_SetParameters(param_table, sizeof(param_table) / sizeof(struct reg_param));
	// Databahn start enable
	SetRegisterField(Databahn_Reg(DATABAHN_REG_START_ADDR), DATABAHN_REG_START_OFFSET, DATABAHN_REG_START_WIDTH, 1);
}

unsigned int Databahn_GetParameter(unsigned int reg, unsigned int offset, unsigned int width)
{
	return GetRegisterField(Databahn_Reg(reg), offset, width);
}

unsigned int Databahn_GetIntStatus(void)
{
	return Databahn_GetParameter(DATABAHN_REG_INT_STATUS_ADDR, DATABAHN_REG_INT_STATUS_OFFSET, DATABAHN_REG_INT_STATUS_WIDTH);
}

unsigned int Databahn_isReady(void)
{
	return (Databahn_GetIntStatus() & 0x20) ? 1 : 0;
}

/* gx6605s_sdram.c */
void gx_setup_sdram_controller(void)
{
	Databahn_Init();
	serial_put_no_mmu('N');
}

